export async function generateMetadata(): Promise<Metadata> {
  const toolData = getToolBySlug(toolSlug);
  if (!toolData) return {};

  return buildMeta({
    title: toolData.seoTitle || toolData.title,
    description: toolData.shortDescription,
    urlPath: `/${toolSlug}`,
  });
}

